contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 role, address account) public {
        require(account != address(this), "account must differ from caller");
        // caller (this contract) holds TIMELOCK_ADMIN_ROLE from deployment,
        // but renouncing for another account must still revert.
        bool reverted;
        try c.renounceRole(role, account) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && !c.hasRole(role, account));
    }

    receive() external payable {}
}

