contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 role, address account) public {
        require(role != bytes32(0));
        require(account != address(0));
        address other = address(uint160(uint256(uint160(account)) ^ 1));

        bool before = c.hasRole(role, account);
        c.grantRole(role, account);
        bool afterA = c.hasRole(role, account);
