contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay);
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id));
        c.schedule(target, value, data, predecessor, salt, delay);
        uint256 tsAfter = c.getTimestamp(id);
        bool rescheduleReverted;
        if (delay == 0) {
            // cannot wait time forward; reschedule would only be checked after cancel
        }
        // cancel is allowed since tsAfter > 1 when block.timestamp >= 1; ensure that
        require(tsAfter > 1);
        bool pendingBefore = c.isOperationPending(id);
        c.cancel(id);
        uint256 tsAfterCancel = c.getTimestamp(id);
        // rescheduling after cancel with the same delay must now succeed and again be exact
        c.schedule(target, value, data, predecessor, salt, delay);
        uint256 tsRescheduled = c.getTimestamp(id);
        assert(pendingBefore && tsAfter == block.timestamp + delay && tsAfterCancel == 0 && tsRescheduled == block.timestamp + delay && c.isOperation(id));
    }
    receive() external payable {}
}

